function build(M) {
  const upper = M.box(2.9, 0.75, 2.3, 0.75);
  const flange = M.box(3, 0.1, 2.4, 1.5);
  const pan = M.T(M.lathe([[0, 0], [0.92, 0], [1, 0.12], [1, 0.75], [0, 0.75]], 40), {s: [1.35, 1, 1.05]});
  const bear = [];
  for (const z of [-1.16, 1.16]) {
    bear.push(M.T(M.cyl(0.38, 0.04, 32, 0), {pos: [0, 1.1, z], rx: 90}));
  }
  const ribs = [];
  for (let i = -4; i <= 4; i++) ribs.push(M.box(0.05, 0.5, 2.24, 0.12, i * 0.28));
  const bolts = [];
  for (let i = 0; i < 10; i++) {
    const x = -1.35 + i * 0.3;
    bolts.push(M.cyl(0.05, 0.05, 12, 1.6).length ? null : M.T(M.cyl(0.05, 0.05, 12, 0), {pos: [x, 1.55, 1.1]}));
  }
  const bl = [];
  for (let i = 0; i < 10; i++) {
    const x = -1.35 + i * 0.3;
    bl.push(M.T(M.cyl(0.05, 0.05, 12, 0), {pos: [x, 1.55, 1.08]}));
    bl.push(M.T(M.cyl(0.05, 0.05, 12, 0), {pos: [x, 1.55, -1.08]}));
  }
  const drain = M.T(M.cyl(0.1, 0.06, 6, 0), {pos: [0.6, 0.06, 0], rx: 180});
  return [
    {material: "dark_steel", look: "solid", mesh: M.merge([upper, pan])},
    {material: "steel", look: "solid", mesh: M.merge([flange, ...bear, ...ribs])},
    {material: "gold", look: "solid", mesh: M.merge([...bl, drain])}
  ];
}

function build(M) {
  const R = 90;
  const main = M.merge([
    M.T(M.cyl(0.16, 0.5, 32, -0.25), {pos: [0, 0, -0.75], rx: R}),
    M.T(M.cyl(0.16, 0.5, 32, -0.25), {pos: [0, 0, 0.75], rx: R}),
    M.T(M.cyl(0.13, 0.3, 32, -0.15), {pos: [0, 0.4, 0], rx: R}),
    M.T(M.cyl(0.2, 0.06, 32, -0.03), {pos: [0, 0, -0.98], rx: R})
  ]);
  const web = [[-0.22, -0.05], [0.22, -0.05], [0.18, 0.5], [-0.18, 0.5]];
  const cw = [];
  for (let i = 0; i <= 12; i++) {
    const a = Math.PI + i * Math.PI / 12;
    cw.push([0.55 * Math.cos(a), 0.55 * Math.sin(a) * 0.95]);
  }
  const webs = [];
  [-0.27, 0.27].forEach(z => {
    webs.push(M.prism(web, z - 0.06, z + 0.06));
    webs.push(M.prism(cw, z - 0.06, z + 0.06));
  });
  const teeth = [];
  for (let i = 0; i < 18; i++) {
    const a = i * 360 / 18;
    teeth.push(M.T(M.box(0.06, 0.08, 0.1, 0.28), {pos: [0, 0, 0], rz: 0, ry: 0}));
    teeth[i] = M.T(teeth[i], {rz: a});
  }
  const gear = M.T(M.merge([M.T(M.cyl(0.3, 0.1, 36, -0.05), {rx: R}), ...teeth.map(t => M.T(t, {pos: [0, 0, 0]}))]), {pos: [0, 0, 0.88]});
  const gearFix = M.T(M.merge([M.T(M.cyl(0.29, 0.1, 36, -0.05), {rx: R}), ...Array.from({length: 18}, (_, i) => M.T(M.box(0.07, 0.07, 0.1, 0.28, 0), {rz: i * 20}))]), {pos: [0, 0, 0.9]});
  return [
    {material: "steel", look: "solid", mesh: main},
    {material: "dark_steel", look: "solid", mesh: M.merge(webs)},
    {material: "copper", look: "solid", mesh: gearFix}
  ];
}

function build(M) {
  const H = 3, W = 2.4, D = 2.2, R = 0.72;
  const parts = [];
  const prof = [[R,0],[1.0,0],[1.0,0.12],[R+0.08,0.12]];
  const body = M.lathe([[R,0],[0.98,0],[0.98,H],[R,H]], 40);
  parts.push(body);
  parts.push(M.box(W, 0.25, D, 0));
  parts.push(M.box(W, 0.25, D, H-0.25));
  for (let i = 0; i < 6; i++) {
    const y = 0.45 + i*0.36;
    parts.push(M.box(W-0.1, 0.08, D-0.1, y));
  }
  for (const sx of [-1,1]) for (const sz of [-1,1]) {
    parts.push(M.cyl(0.18, H, 20, 0, 0), );
    parts[parts.length-1] = M.T(parts[parts.length-1], {pos:[sx*(W/2-0.22),0,sz*(D/2-0.22)]});
  }
  const iron = M.merge(parts);
  const bore = M.tube(R, H, 40);
  const boreM = M.T(bore, {pos:[0,H/2,0]});
  const bolts = [];
  for (const sx of [-1,1]) for (const sz of [-1,1]) {
    bolts.push(M.T(M.cyl(0.09, 0.04, 16, H), {pos:[sx*(W/2-0.22),0,sz*(D/2-0.22)]}));
    bolts.push(M.T(M.cyl(0.09, 0.04, 16, -0.04), {pos:[sx*(W/2-0.22),0,sz*(D/2-0.22)]}));
  }
  const rim = M.merge([M.T(M.torus(R+0.02, 0.03, 40, 8), {pos:[0,H+0.01,0]}), M.T(M.torus(R+0.02,0.03,40,8),{pos:[0,-0.01,0]})]);
  const ports = M.merge([M.T(M.pipe([W/2-0.02,2.2,0.45],[W/2+0.0,2.2,0.45],0.15,20),{}), M.T(M.pipe([W/2-0.02,2.2,-0.45],[W/2,2.2,-0.45],0.15,20),{})]);
  return [
    {material:"dark_steel", look:"solid", mesh: iron},
    {material:"steel", look:"solid", mesh: boreM},
    {material:"black" === "x" ? "steel" : "steel", look:"solid", mesh: M.merge([...bolts])},
    {material:"copper", look:"solid", mesh: rim},
    {material:"blue", look:"solid", mesh: ports}
  ];
}

