function build(M) {
  const head = M.lathe([[0,0],[0.15,0],[0.15,0.025],[0.11,0.05],[0.04,0.12],[0.025,0.18],[0,0.18]], 40);
  const stem = M.cyl(0.022, 0.7, 20, 0.16);
  const tip = M.cyl(0.026, 0.04, 20, 0.86);
  const keeper = M.frustum(0.045, 0.06, 0.05, 24, 0.79);
  const steel = M.merge([head, stem, tip, keeper]);
  const coils = [];
  const turns = 6, n = turns * 24, R = 0.085, r = 0.014, y0 = 0.44, y1 = 0.78;
  let prev = null;
  for (let i = 0; i <= n; i++) {
    const a = i / 24 * Math.PI * 2, y = y0 + (y1 - y0) * i / n;
    const p = [R * Math.cos(a), y, R * Math.sin(a)];
    if (prev) coils.push(M.pipe(prev, p, r, 8));
    prev = p;
  }
  const seatBot = M.cyl(0.1, 0.02, 32, 0.42);
  const retainer = M.cyl(0.1, 0.02, 32, 0.78);
  return [
    {material: "steel", look: "solid", mesh: steel},
    {material: "blue", look: "solid", mesh: M.merge(coils)},
    {material: "dark_steel", look: "solid", mesh: M.merge([seatBot, retainer])}
  ];
}

function build(M) {
