  const spring = M.merge(coils);
  const retainer = M.merge([M.frustum(0.05,0.1,0.03,32,0.36), M.T(M.cyl(0.1,0.015,32,0),{pos:[0,0.39,0]})]);
  const seat = M.cyl(0.1,0.012,32,0.03);
