}

function build(M) {
  const seg = 32;
  const thread = [];
  for (let i = 0; i < 8; i++) thread.push(M.T(M.torus(0.075, 0.012, 24, 6), {pos: [0, 0.03 + i * 0.022, 0]}));
  const core = M.cyl(0.07, 0.19, seg, 0.0);
  const nut = M.cyl(0.13, 0.08, 6, 0.2);
  const washer = M.cyl(0.1, 0.012, seg, 0.19);
  const hook = M.merge([M.pipe([0.07, 0.0, 0], [0.07, -0.04, 0], 0.012, 8), M.pipe([0.07, -0.04, 0], [0, -0.04, 0], 0.012, 8), M.cyl(0.012, 0.03, 8, -0.03)]);
  const metal = M.merge([core, nut, washer, hook].concat(thread));
  const ceramic = M.lathe([[0.001, 0.28], [0.1, 0.28], [0.095, 0.32], [0.075, 0.36], [0.07, 0.56], [0.001, 0.56]], seg);
  const ribs = [];
  for (let i = 0; i < 5; i++) ribs.push(M.T(M.torus(0.072, 0.012, 24, 8), {pos: [0, 0.39 + i * 0.035, 0]}));
  const cap = M.merge([M.lathe([[0.001, 0.54], [0.085, 0.54], [0.09, 0.6], [0.075, 0.68], [0.001, 0.7]], seg), M.pipe([0, 0.68, 0], [-0.13, 0.74, 0], 0.03, 12)]);
  return [
    {material: "steel", look: "solid", mesh: metal},
    {material: "white", look: "solid", mesh: M.merge([ceramic].concat(ribs))},
    {material: "dark_steel", look: "solid", mesh: cap}
  ];
}

